# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""Lifecycle gate emitter — drives v3 §6.5 ``gate_events`` from the plugin.

Thin Python wrapper around ``synaptory telemetry gate-event``. Used by
the scrum / kanban state machines and ceremony Python helpers to record
gate transitions as the orchestrator runs:

- Project Inception completion → ``project_inception / approved``
- Sprint Planning end → ``spec_ready / opened`` per accepted spec
- Sprint Review accept_story (#116) → ``evidence_dod / approved``
- Sprint Review reject_story (#116) → ``evidence_dod / rejected``
- Release ceremony exit → ``release / approved``

The emitter is **best-effort**: a failing CLI call writes a stderr
warning but never raises (gate emission must never block a ceremony).
The CLI itself queues to the outbox when the CP is unreachable, so a
network blip doesn't lose the event.
"""

from __future__ import annotations

import os
import shutil
import hashlib
import json
import subprocess
import sys
from pathlib import Path
from typing import Iterable, Literal

GateType = Literal[
    "project_inception", "spec_ready", "evidence_dod", "release", "dependency",
]
TargetType = Literal[
    "project", "spec_version", "release", "work_unit", "cycle",
]
State = Literal[
    "opened", "approved", "rejected", "returned", "superseded",
]
DecisionRole = Literal[
    "delivery_owner", "compliance_reviewer", "global_admin",
]


# Kept EQUAL to `api/synaptory_api/models.py`'s `GateEvent.GATE_TYPES` and
# `TARGET_TYPES`, and pinned equal by a test.
#
# These drifted once already: PR #317 widened the server side so dependency
# events could ride `GateEvent` rather than need their own table
# (`gate_type: dependency`, `target_type: work_unit`/`cycle`), and this module
# lagged -- so the schema shipped with nothing able to emit into it. Design
# §13.2 says the gate vocabulary is frozen; that sentence predates #317 and is
# amended there. A Coordination Cycle still emits only the existing `release`
# gate (#305).
_GATE_TYPES = {
    "project_inception", "spec_ready", "evidence_dod", "release", "dependency",
}
_TARGET_TYPES = {
    "project", "spec_version", "release", "work_unit", "cycle",
}
_STATES = {"opened", "approved", "rejected", "returned", "superseded"}
_DECISION_ROLES = {"delivery_owner", "compliance_reviewer", "global_admin"}


#: Printed once per process when the runtime cannot tell which control plane it
#: belongs to. Module-level so the message is emitted once rather than per
#: emission — a ceremony emits one gate event per spec, and 40 identical
#: paragraphs would bury the ceremony's own output.
_UNADDRESSED_WARNED = False


def _warn_unaddressed() -> None:
    global _UNADDRESSED_WARNED
    if _UNADDRESSED_WARNED:
        return
    _UNADDRESSED_WARNED = True
    print(
        "gate_emitter: not emitting — this runtime tree has no control-plane "
        "stamp, so there is no way to tell which control plane it reports to. "
        "Run `./synaptory deploy local` (writes hooks/lib/cp-url.local) for a "
        "local stack, install the marketplace plugin for production, or set "
        "SYNAPTORY_CLI_BIN to an explicit binary for CI. Emitting anyway would "
        "address production from an unstamped tree (#320).",
        file=sys.stderr,
    )


def _resolve_cli() -> str | None:
    """Resolve the synaptory CLI path.

    Mirrors hooks/_resolve-cli.sh: explicit override, otherwise choose the
    channel sibling matching the active plugin's immutable CP stamp.

    An unstamped tree resolves NOTHING rather than falling through to
    `synaptory`. That fall-through was #320: a source-tree run has no stamp in
    its environment, so every gate event a locally-run ceremony emitted was
    addressed to https://synaptory.h3t.co, 404'd on a project that only exists
    locally, and queued to the outbox forever — 76 stranded project directories
    over two months. "No stamp" is not "production"; the two are only the same
    if you are willing to guess, and guessing wrong ships local data to prod on
    the first slug collision. `SYNAPTORY_CLI_BIN` stays the explicit escape
    hatch for CI and e2e, which have no plugin tree to stamp.
    """
    try:
        from host_env import channel_signal

        # One call, not two: the signal reads the stamp off disk, and a ceremony
        # emits one gate event per spec.
        local, channel_source = channel_signal()
    except Exception:
        local = False
        channel_source = ""
    identity_known = bool(channel_source)

    def identity_matches(candidate: str, *, explicit: bool = False) -> bool:
        if not identity_known:
            return True
        try:
            probe = subprocess.run(
                [candidate, "status"],
                capture_output=True,
                text=True,
                check=False,
                timeout=2.0,
            )
            identity = next(
                (
                    line.split(":", 1)[1].strip()
                    for line in probe.stdout.splitlines()
                    if line.startswith("control_plane_url:")
                ),
                "",
            )
            # Explicit CI shims may not implement status. A real CLI that does
            # expose its identity must match the immutable plugin channel.
            if not identity:
                return explicit
            from host_env import is_loopback_url

            return is_loopback_url(identity) == local
        except (OSError, subprocess.SubprocessError, StopIteration):
            return explicit

    override = os.environ.get("SYNAPTORY_CLI_BIN")
    if override and os.path.isfile(override) and os.access(override, os.X_OK):
        return override if identity_matches(override, explicit=True) else None

    if not channel_source:
        _warn_unaddressed()
        return None

    name = "synaptory-local" if local else "synaptory"
    candidates: list[Path] = []
    discovered = shutil.which(name)
    if discovered:
        candidates.append(Path(discovered))
    if local:
        prod = shutil.which("synaptory")
        if prod:
            candidates.append(Path(prod).parent / name)
    candidates.extend((Path.home() / ".local" / "bin" / name, Path.home() / "bin" / name))
    seen: set[str] = set()
    for candidate in candidates:
        rendered = str(candidate)
        if rendered in seen or not candidate.is_file() or not os.access(candidate, os.X_OK):
            continue
        seen.add(rendered)
        if not identity_matches(rendered):
            continue
        return rendered
    return None


def emit_gate_event(
    *,
    gate_type: GateType,
    target_type: TargetType,
    target_id: str,
    state: State,
    decided_by: str | None = None,
    decision_role: DecisionRole | None = None,
    reason: str | None = None,
    timeout: float = 10.0,
    project_dir: str | None = None,
) -> bool:
    """Post a single gate event via ``synaptory telemetry gate-event``.

    Returns ``True`` on success (or successful outbox-queue), ``False``
    on any failure. Never raises — gate emission must not block a
    ceremony.
    """
    # Validate enums before shelling out so a typo surfaces here, not
    # buried inside CLI stderr. Mirrors the api-side validation.
    if gate_type not in _GATE_TYPES:
        print(
            f"gate_emitter: refusing to emit — invalid gate_type {gate_type!r}; "
            f"expected one of {sorted(_GATE_TYPES)}",
            file=sys.stderr,
        )
        return False
    if target_type not in _TARGET_TYPES:
        print(
            f"gate_emitter: refusing to emit — invalid target_type "
            f"{target_type!r}; expected one of {sorted(_TARGET_TYPES)}",
            file=sys.stderr,
        )
        return False
    if state not in _STATES:
        print(
            f"gate_emitter: refusing to emit — invalid state {state!r}; "
            f"expected one of {sorted(_STATES)}",
            file=sys.stderr,
        )
        return False
    if decision_role is not None and decision_role not in _DECISION_ROLES:
        print(
            f"gate_emitter: refusing to emit — invalid decision_role "
            f"{decision_role!r}; expected one of {sorted(_DECISION_ROLES)}",
            file=sys.stderr,
        )
        return False

    cli = _resolve_cli()
    if cli is None:
        # CLI not installed yet — emission is silently skipped. This is
        # the same fallback path other hooks use; the operator install
        # script (cli/install.sh) is the canonical fix.
        return False

    cmd: list[str] = [
        cli, "telemetry", "gate-event",
        "--gate-type", gate_type,
        "--target-type", target_type,
        "--target-id", target_id,
        "--state", state,
        "--quiet",
    ]
    if decided_by:
        cmd += ["--decided-by", decided_by]
    if decision_role:
        cmd += ["--decision-role", decision_role]
    if reason:
        cmd += ["--reason", reason]

    try:
        run_options = {
            "capture_output": True,
            "text": True,
            "timeout": timeout,
        }
        # The CLI resolves project_id by walking up from cwd. MCP servers run
        # from the installed plugin root, not the governed project, so omitting
        # cwd silently queued/shipped unbound gate events and left /quality
        # without authoritative computed DoD rows.
        if project_dir:
            run_options["cwd"] = project_dir
        result = subprocess.run(cmd, **run_options)
    except (subprocess.TimeoutExpired, OSError) as e:
        print(
            f"gate_emitter: {gate_type}/{state} for {target_id} — "
            f"{type(e).__name__}; CLI outbox should retry on next session.",
            file=sys.stderr,
        )
        return False

    if result.returncode != 0:
        # Best-effort: log the failure with the CLI's stderr tail so the
        # operator can diagnose, but never block the ceremony.
        tail = (result.stderr or result.stdout or "").strip().splitlines()
        last = tail[-1] if tail else f"exit {result.returncode}"
        print(
            f"gate_emitter: {gate_type}/{state} for {target_id} failed "
            f"({last}); queued for retry on the next session.",
            file=sys.stderr,
        )
        _spool(cmd[1:], project_dir)
        return False
    _retry_pending(project_dir)
    return True


# ── Retry spool ─────────────────────────────────────────────────────────────
#
# The message above used to promise "CLI outbox should retry on next session",
# and for a network or auth failure that is true -- the CLI queues those itself.
# It is NOT true for the failure actually observed: `no project_id resolved`
# returns before the CLI reaches its outbox, so the event was dropped and the
# reassuring message was wrong. One workstream emitted ZERO gate events for a
# whole Cycle that way (#331 G10).
#
# Same shape as `manifest_emitter`'s spool (#334), deliberately: two emitters
# with the same failure mode should not have two different recovery stories.
_SPOOL_RELDIR = ("gate-events",)
_SPOOL_MAX = 200


def _spool_dir(project_dir: str | None) -> str | None:
    if not project_dir:
        return None
    return os.path.join(
        str(project_dir), ".synaptory", ".orchestrator", *_SPOOL_RELDIR
    )


def _spool(args: list, project_dir: str | None) -> None:
    """Park a failed gate event for a later session to re-send.

    Stores the ARGUMENTS, not the resolved CLI path. The binary can move or be
    updated between sessions, and a spool that pins an absolute path would
    retry a file that is no longer there.
    """
    directory = _spool_dir(project_dir)
    if not directory:
        return
    try:
        os.makedirs(directory, exist_ok=True)
        # Keyed on the command itself, so re-emitting an identical event
        # overwrites rather than accumulating. Two DIFFERENT events never
        # collide, because the argv carries the target and state.
        digest = hashlib.sha256(
            "\x00".join(str(part) for part in args).encode("utf-8")
        ).hexdigest()[:32]
        path = os.path.join(directory, digest + ".json")
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump({"args": [str(part) for part in args]}, handle)
        os.replace(tmp, path)

        entries = sorted(
            (os.path.getmtime(os.path.join(directory, f)), f)
            for f in os.listdir(directory) if f.endswith(".json")
        )
        if len(entries) > _SPOOL_MAX:
            for _, stale in entries[:len(entries) - _SPOOL_MAX]:
                try:
                    os.unlink(os.path.join(directory, stale))
                except OSError:
                    pass
    except Exception:  # noqa: BLE001 - observation must never block a ceremony
        pass


def retry_pending(project_dir: str) -> int:
    """Re-send every spooled gate event. Returns how many landed.

    Gate events are append-only and carry a client event id, so the server
    de-duplicates a re-send. An entry is removed only on success.
    """
    directory = _spool_dir(project_dir)
    if not directory or not os.path.isdir(directory):
        return 0
    try:
        names = sorted(f for f in os.listdir(directory) if f.endswith(".json"))
    except OSError:
        return 0
    cli = _resolve_cli()
    if cli is None:
        # Nothing to send with. Leave the spool intact: the CLI being absent is
        # a separate problem, and discarding the backlog to "clean up" would
        # lose the events it exists to protect.
        return 0
    sent = 0
    for name in names:
        path = os.path.join(directory, name)
        try:
            with open(path, encoding="utf-8") as handle:
                args = json.load(handle).get("args")
        except Exception:  # noqa: BLE001 - a corrupt entry is dropped, not retried forever
            try:
                os.unlink(path)
            except OSError:
                pass
            continue
        if not isinstance(args, list) or not args:
            try:
                os.unlink(path)
            except OSError:
                pass
            continue
        try:
            result = subprocess.run(
                [cli, *[str(a) for a in args]], capture_output=True, text=True,
                timeout=10.0, cwd=project_dir,
            )
        except (subprocess.TimeoutExpired, OSError):
            continue
        if result.returncode == 0:
            sent += 1
            try:
                os.unlink(path)
            except OSError:
                pass
    return sent


def _retry_pending(project_dir: str | None) -> None:
    """Drain on any successful emit, so the spool cannot outlive its cause."""
    if project_dir:
        try:
            retry_pending(project_dir)
        except Exception:  # noqa: BLE001
            pass


def emit_spec_ready_opened(
    spec_ids: Iterable[str], *, project_dir: str | None = None,
) -> int:
    """Convenience: emit `spec_ready / opened` for each spec in a sprint plan.

    Called at the end of Sprint Planning when the orchestrator commits
    the sprint backlog. Returns the count of successful emissions.
    """
    n = 0
    for sid in spec_ids:
        if emit_gate_event(
            gate_type="spec_ready",
            target_type="spec_version",
            target_id=sid,
            state="opened",
            project_dir=project_dir,
        ):
            n += 1
    return n


