def emit_dependency_published(
    target_id: str,
    *,
    target_type: str = "work_unit",
    published_by: str = "",
    reason: str = "",
    project_dir: str | None = None,
) -> bool:
    """Emit when a dependency condition is published (#303 §3, #305).

    PR #317 widened `GateEvent` for exactly this -- `gate_type: dependency`,
    `target_type: work_unit`/`cycle` -- and then nothing emitted it, so the one
    record that explains WHY a Work Unit was blocked or unblocked never reached
    the control plane. A reader could see the gate transitions around a Cycle
    and still not learn what satisfied a dependency, or when.

    `state: "approved"` because a published event is a settled fact: it is
    written only after producer-side verification succeeded.
    """
    return emit_gate_event(
        gate_type="dependency",
        target_type=target_type,
        target_id=target_id,
        state="approved",
        decided_by=published_by,
        decision_role="delivery_owner",
        reason=reason or None,
        project_dir=project_dir,
    )


def emit_release_approved(
    release_id: str, approved_by: str, *, project_dir: str | None = None,
) -> bool:
    """Emit when the release ceremony completes."""
    return emit_gate_event(
        gate_type="release",
        target_type="release",
        target_id=release_id,
        state="approved",
        decided_by=approved_by,
        decision_role="delivery_owner",
        project_dir=project_dir,
    )
